seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

# Find ORFs on both strands, six frames
comp = str.maketrans("ACGT","TGCA")
rc = seq.translate(comp)[::-1]
stop = {"TAA","TAG","TGA"}
def find_orfs(s, label):
    orfs=[]
    for frame in range(3):
        i=frame
        start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=="ATG" and start is None:
                start=i
            if cod in stop and start is not None:
                orfs.append((start,i+3,i+3-start,label,frame))
                start=None
            i+=3
    return orfs

orfs = find_orfs(seq,"+")+find_orfs(rc,"-")
orfs.sort(key=lambda x:-x[2])
for o in orfs[:12]:
    print(o)

